def conservar_intentos_anteriores(apps, schema_editor):
    """Una sola vez: guarda las credenciales antiguas para conciliar sus avisos pendientes.
    Después del cambio las ventas nunca vuelven a consultar las llaves de .env.
    """
    import json
    from core.cifrado import cifrar

    if not (settings.WOMPI_PUBLIC_KEY and settings.WOMPI_INTEGRITY_SECRET and settings.WOMPI_EVENTS_SECRET):
        return
    Pago = apps.get_model("core", "Pago")
    pendientes = Pago.objects.using(schema_editor.connection.alias).filter(credenciales_cifradas="")
    if pendientes.exists():
        token = cifrar(json.dumps({
            "publica": settings.WOMPI_PUBLIC_KEY,
            "modo": "pruebas" if settings.WOMPI_PUBLIC_KEY.startswith("pub_test_") else "produccion",
            "privada": settings.WOMPI_PRIVATE_KEY,
            "integridad": settings.WOMPI_INTEGRITY_SECRET,
            "eventos": settings.WOMPI_EVENTS_SECRET,
        }))
        pendientes.update(credenciales_cifradas=token)


